/**
 * Normaliza um texto para comparação canônica sem interferência de pontuação, espaços, quebras ou maiúsculas.
 */
function normalizeTextForComparison(text: string): string {
  if (!text) return '';
  return text
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // remove acentos para flexibilidade
    .replace(/[\s\r\n\t\.,;:\-"'«»“”!?()_\/\\\[\]{}*#]/g, '');
}

/**
 * Verifica se um texto corresponde a uma das redações homologadas do Banco Oficial Nota 1000.
 */
export function isOfficialNota1000Benchmark(text: string): boolean {
  if (!text || text.trim().length < 50) return false;
  const cleanInput = normalizeTextForComparison(text);
  if (cleanInput.length < 50) return false;

  return NOTA_1000_SAMPLES.some(sample => {
    const cleanSample = normalizeTextForComparison(sample.fullText);
    if (cleanInput === cleanSample) return true;
    if (cleanInput.length >= 80 && cleanSample.length >= 80) {
      const sampleHead = cleanSample.slice(0, 80);
      const inputHead = cleanInput.slice(0, 80);
      if (cleanInput.includes(sampleHead) || cleanSample.includes(inputHead)) return true;
    }
    return false;
  });
}

/**
 * Encontra a redação correspondente no Banco Oficial Nota 1000, caso exista.
 */
export function findMatchingOfficialSample(text: string): Nota1000Sample | undefined {
  if (!text || text.trim().length < 50) return undefined;
  const cleanInput = normalizeTextForComparison(text);
  if (cleanInput.length < 50) return undefined;

  return NOTA_1000_SAMPLES.find(sample => {
    const cleanSample = normalizeTextForComparison(sample.fullText);
    if (cleanInput === cleanSample) return true;
    if (cleanInput.length >= 80 && cleanSample.length >= 80) {
      const sampleHead = cleanSample.slice(0, 80);
      const inputHead = cleanInput.slice(0, 80);
      if (cleanInput.includes(sampleHead) || cleanSample.includes(inputHead)) return true;
    }
    return false;
  });
}
